const body = $json.body || $json;
const binaryKeys = Object.keys($binary || {});
const eventType = String(body.event_type || (body.answers ? 'candidate_response' : 'resume_applied')).trim();
const resumeText = String(body.resume_text || body.resume || body.cover_text || '').trim();
