return [{
  json: {
    request_id: body.request_id || `req-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    event_type: eventType,
    candidate_id: candidateId,
    candidate_name: String(body.candidate_name || body.name || '').trim(),
    email: String(body.email || body.candidate_email || '').trim(),
    phone: String(body.phone || '').trim(),
    job_id: jobId,
    jd_text: String(body.jd_text || '').trim(),
    resume_text: resumeText,
    answers: body.answers || body.response_answers || {},
    source: String(body.source || 'webhook').trim(),
    resume_binary_key: binaryKeys[0] || '',
    response_base_url: String(body.response_base_url || $env.N8N_PUBLIC_BASE_URL || '').trim(),
    shortlist_size: Number(body.shortlist_size || 10),
    weights: { match: 0.6, interest: 0.4 },
    received_at: new Date().toISOString()
  }
}];

function safeParse(text) {
  if (!text || typeof text !== 'string') return null;
  const cleaned = text.replace(/```json|```/gi, '').trim();
  try { return JSON.parse(cleaned); } catch {}
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch {}
  }
  return null;
}

function fallbackProfile(text) {
  const low = String(text || '').toLowerCase();
  const skillBank = ['python','javascript','typescript','node.js','react','llm','gemini','fastapi','aws','gcp','azure','postgres','vector','pgvector','docker','kubernetes','etl','api','automation','n8n'];
  const skills = skillBank.filter((skill) => low.includes(skill.replace('.js', ''))).slice(0, 12);
  const experienceYears = Math.min(20, Math.max(0, (low.match(/(\d+)\+?\s+years?/g) || ['3 years'])[0].match(/\d+/)?.[0] ? Number((low.match(/(\d+)\+?\s+years?/g) || ['3 years'])[0].match(/\d+/)[0]) : 3));
  return { candidate_name: $json.candidate_name || 'Unknown Candidate', email: $json.email || '', phone: $json.phone || '', skills, years_experience: experienceYears, projects: [], current_title: '', summary: 'Parsed by fallback profile extractor' };
}

const parsed = safeParse($json.text || $json.output || '');
const profile = parsed && Array.isArray(parsed.skills) ? parsed : fallbackProfile($json.resume_text);
const normalizedSkills = [...new Set((profile.skills || []).map((s) => String(s).trim()).filter(Boolean))];
const searchableText = [profile.candidate_name, profile.current_title, profile.summary, (profile.projects || []).join(' '), normalizedSkills.join(' ')].filter(Boolean).join(' ');

return [{
  json: {
    ...$json,
    resume_profile: {
      candidate_name: String(profile.candidate_name || $json.candidate_name || 'Unknown Candidate').trim(),
      email: String(profile.email || $json.email || '').trim(),
      phone: String(profile.phone || $json.phone || '').trim(),
      skills: normalizedSkills,
      years_experience: Number(profile.years_experience || 0),
      projects: Array.isArray(profile.projects) ? profile.projects : [],
      current_title: String(profile.current_title || '').trim(),
      summary: String(profile.summary || '').trim()
    },
    resume_search_text: searchableText,
    resume_contract_valid: Boolean(profile.candidate_name)
  }
}];

function makeVector(text, size = 16) {
  const vector = new Array(size).fill(0);
  const tokens = String(text || '').toLowerCase().split(/\W+/).filter(Boolean);
  for (const token of tokens) {
    let hash = 0;
    for (let i = 0; i < token.length; i++) hash = ((hash << 5) - hash) + token.charCodeAt(i);
    const index = Math.abs(hash) % size;
    vector[index] += 1;
  }
  const norm = Math.sqrt(vector.reduce((sum, value) => sum + (value * value), 0)) || 1;
  return vector.map((value) => Number((value / norm).toFixed(6)));
}

const embedding = makeVector($json.resume_search_text || $json.resume_text || '', 16);
const embeddingLiteral = '[' + embedding.join(',') + ']';
const profileSql = JSON.stringify($json.resume_profile).replace(/'/g, "''");

return [{
  json: {
    ...$json,
    resume_embedding: embeddingLiteral,
    resume_profile_sql: profileSql
  }
}];

