const parsed = safeParse($json.text || $json.output || '');
const skillOverlap = Array.isArray(parsed?.skill_overlap) ? parsed.skill_overlap : ($json.resume_profile.skills || []).filter((skill) => String(($json.job_context.parsed_json?.skills || []).map((s) => s.name || s).join(' ')).toLowerCase().includes(String(skill).toLowerCase()));
const skillGap = Array.isArray(parsed?.skill_gap) ? parsed.skill_gap : [];
const skillScore = Number(parsed?.skill_score ?? Math.min(100, skillOverlap.length * 20));
const expScore = Number(parsed?.experience_score ?? Math.max(0, 100 - Math.abs((Number($json.resume_profile.years_experience || 0)) - Number($json.job_context.parsed_json?.min_years_experience || 3)) * 20));
const semanticScore = Number(parsed?.semantic_score ?? $json.job_context.vector_similarity ?? 50);
const matchScore = Math.max(0, Math.min(100, Math.round(skillScore * 0.4 + expScore * 0.3 + semanticScore * 0.3)));

return [{
  json: {
    ...$json,
    match_result: {
      match_score: matchScore,
      match_explanation: parsed?.match_explanation || 'Fallback match based on resume skills, experience alignment, and JD similarity.',
      skill_overlap: skillOverlap,
      skill_gap: skillGap,
      skill_score: skillScore,
      experience_score: expScore,
      semantic_score: semanticScore
    },
    match_contract_valid: true
  }
}];

