function safeParse(text) {
  if (!text || typeof text !== 'string') return null;
  const cleaned = text.replace(/```json|```/gi, '').trim();
  try { return JSON.parse(cleaned); } catch {}
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch {}
  }
  return null;
}

const parsed = safeParse($json.text || $json.output || '');
const questions = Array.isArray(parsed?.questions) ? parsed.questions.slice(0, 8) : [];
const skillGap = $json.match_result.skill_gap || [];
const fallbackQuestions = [];
for (const gap of skillGap.slice(0, 3)) {
  fallbackQuestions.push({ question: `Describe your hands-on experience with ${gap} and how you have used it in a production setting.`, type: 'skill_validation', reason: 'Validates a missing skill gap' });
}
fallbackQuestions.push({ question: 'Walk us through the most relevant project from your resume for this role and what you personally owned.', type: 'experience_deep_dive', reason: 'Checks depth of experience' });
fallbackQuestions.push({ question: 'Why are you interested in this role right now, and what would make this opportunity a priority for you?', type: 'commitment_interest', reason: 'Measures commitment and intent' });
fallbackQuestions.push({ question: 'If we were to move quickly, what is your realistic availability window to start?', type: 'availability_intent', reason: 'Checks availability' });

const finalQuestions = (questions.length >= 5 ? questions : fallbackQuestions).slice(0, 8);
const questionsSql = JSON.stringify(finalQuestions).replace(/'/g, "''");

return [{
  json: {
    ...$json,
    generated_questions: finalQuestions,
    generated_questions_sql: questionsSql,
    questions_contract_valid: finalQuestions.length >= 5 && finalQuestions.length <= 8
  }
}];

const questions = $json.generated_questions || [];
const responseLink = `${$json.response_base_url || ''}/webhook/recruitment/v2?event_type=candidate_response&candidate_id=${encodeURIComponent($json.candidate_id)}&job_id=${encodeURIComponent($json.job_context.job_id)}`;
const questionList = questions.map((item, index) => `<li><strong>Q${index + 1}:</strong> ${item.question}</li>`).join('');

return [{
  json: {
    ...$json,
    response_link: responseLink,
    email_subject: `Next step for ${$json.resume_profile.candidate_name} - ${$json.job_context.title || 'Your application'}`,
    email_html: `<html><body><p>Hi ${$json.resume_profile.candidate_name},</p><p>Thanks for your application for <strong>${$json.job_context.title || 'this role'}</strong>.</p><p>Please complete the short follow-up form here:</p><p><a href='${responseLink}'>${responseLink}</a></p><p>Questions:</p><ol>${questionList}</ol><p>Best,<br/>Recruiting Automation Agent</p></body></html>`
  }
}];

function safeParse(text) {
  if (!text || typeof text !== 'string') return null;
  const cleaned = text.replace(/```json|```/gi, '').trim();
  try { return JSON.parse(cleaned); } catch {}
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch {}
  }
  return null;
}

const parsed = safeParse($json.text || $json.output || '');
const answerText = JSON.stringify($json.answers || {});
const textLength = answerText.length;
const intentClarity = Number(parsed?.intent_clarity ?? Math.min(100, Math.max(20, Math.round(textLength / 4))));
const engagementDepth = Number(parsed?.engagement_depth ?? Math.min(100, Math.max(20, Math.round(textLength / 3))));
const roleAlignment = Number(parsed?.role_alignment ?? 55);
const interestScore = Math.max(0, Math.min(100, Number(parsed?.interest_score ?? Math.round(intentClarity * 0.4 + engagementDepth * 0.3 + roleAlignment * 0.3))));
const intentLevel = parsed?.intent_level || (interestScore >= 75 ? 'high' : interestScore >= 50 ? 'medium' : 'low');

return [{
  json: {
    ...$json,
    interest_result: {
      interest_score: interestScore,
      interest_explanation: parsed?.interest_explanation || 'Fallback interest scoring used because Gemini output was unavailable.',
      intent_level: intentLevel,
      intent_clarity: intentClarity,
      engagement_depth: engagementDepth,
      role_alignment: roleAlignment
    },
    interest_contract_valid: true
  }
}];

const matchScore = Number($json.match_score || $json.match_result?.match_score || 0);
const interestScore = Number($json.interest_result?.interest_score || 0);
const finalScore = Math.max(0, Math.min(100, Math.round(matchScore * 0.6 + interestScore * 0.4)));
const recommended = finalScore >= 75 && matchScore >= 60 && interestScore >= 55;

return [{
  json: {
    candidate_name: $json.candidate_name || $json.candidate_id || 'Unknown Candidate',
    match_score: Math.round(matchScore),
    interest_score: Math.round(interestScore),
    final_score: finalScore,
    match_explanation: $json.match_explanation || $json.match_result?.match_explanation || 'Match evaluation completed with fallback logic.',
    interest_explanation: $json.interest_result?.interest_explanation || 'Interest evaluation completed with fallback logic.',
    recommended,
    intent_level: $json.interest_result?.intent_level || 'low',
    candidate_id: $json.candidate_id,
    job_id: $json.job_id,
    responses: $json.answers || {},
    questions: $json.questions || [],
    updated_at: new Date().toISOString()
  }
}];
